import { Component, Input, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { PmoaService } from 'src/app/services/emis/pmoa.services';
import { UserSessionService } from 'src/app/services/usersession.service';


@Component({
  selector: 'app-school-list',
  templateUrl: './school-list.page.html',
  styleUrls: ['./school-list.page.scss'],
})
export class SchoolListPage implements OnInit {

  UserName: any;
  count: any;
  useriddata: any;
  RcvdSchoolCount: any;
  NotRcvdSchlCount: any;
  countdata: any=[];
  schlist: any;
  type: any;
  scholid: any;
  school: any;
  student_id: any;
  BlockId: any;
  SchoolId: any;
  SchoolName: any;
  section: any;
  class: any;
  routeData: any;
  stutlist: any;
  stu_id: any;
  searchData: any[];
  searchTerm: any;
  allschlist: any;
  


  constructor(private router: Router,private usersessionService: UserSessionService, private pmoaService: PmoaService,private route: ActivatedRoute) { }

  ngOnInit() {
  }

  ionViewWillEnter() {
    this.UserName = this.usersessionService.emis_username();
    this.useriddata = this.usersessionService.user_id();
    this.getdata()
    this.getschoolist()
    this.routeData = this.route.snapshot;
    this.section = this.routeData.queryParams.section;
    this.class = this.routeData.queryParams.class;
  }
  

  onGoButton() {
    
    this.router.navigate(['/tabs/home'])
  }

  navigateToClassSection(data,id){
    console.log(data,'data')
 
    this.stu_id = id
    this.router.navigate(['/tabs/ndd/class-list'], {
      queryParams: { id: data.BlockId, school_id: data.SchoolId, school_name: data.SchoolName,class:this.class,section:this.section }
    });
console.log( data.BlockId, data.SchoolId,data.SchoolName,this.class,this.section)
   
  }
  getdata(){
 
    this.pmoaService.schoolcount(this.useriddata).subscribe((res) => {
      this.countdata = res.result
      this.count = this.countdata.TotSchlCount[0].Count;
      this.RcvdSchoolCount = this.countdata.RcvdCount[0].RcvdSchoolCount;
      this.NotRcvdSchlCount = this.countdata.RcvdCount[0].NotRcvdSchlCount;

    })
    
  }

  getFilterItems(event) {
    
    // this.searchData = this.schlist.filter((item: any) => {
    //   return item.SchoolName.toLowerCase().indexOf(event.detail.value.toLowerCase()) > -1;
    // });
    this.schlist = [];
    this.searchTerm = event.detail.value.trim();
    this.schlist = this.allschlist.filter((item) => {
      return item.SchoolName.toLowerCase().indexOf(this.searchTerm.toLowerCase()) > -1;
    });
  }

  getschoolist(){
    this.pmoaService.schoollist(this.useriddata).subscribe((res) => {
        this.schlist = res.result
        this.allschlist = res.result
    })
  }

}


